    process.exit(0);
    return;
  }

  const text = raw.trim();
  let payload: unknown;
  try {
    payload = JSON.parse(text);
  } catch (err) {
    process.stdout.write(`INVALID: invalid JSON: ${(err as Error).message}\n`);
    process.exit(0);
    return;
  }

  const result = validateDiscount(payload);
